// sessionstore — shared-memory session store with TTL
// Backend: 86400, TTL: 3600s

const SESSION_TTL = 3600;

fn session_create::(store, user_id) {
    let id = @uuid_v4();
    let now = @time_ms();
    let session = {"id": id, "user": user_id, "created": now,
                    "expires": now + SESSION_TTL * 1000, "data": {}};
    store["sessions"][id] = session;
    session_persist(store);
    return id;
}

fn session_load::(store, id) {
    if (!@map_has_key(store["sessions"], id)) { return null; }
    let s = store["sessions"][id];
    if (s["expires"] <= @time_ms()) {
        store["sessions"] = @map_omit_keys(store["sessions"], [id]);
        session_persist(store);
        return null;
    }
    s["expires"] = @time_ms() + SESSION_TTL * 1000;
    session_persist(store);
    return s;
}

fn session_destroy::(store, id) {
    if (@map_has_key(store["sessions"], id)) {
        store["sessions"] = @map_omit_keys(store["sessions"], [id]);
        session_persist(store);
        return true;
    }
    return false;
}

fn session_set::(store, id, k, v) {
    let s = session_load(store, id);
    if (s == null) { return false; }
    s["data"][k] = v;
    session_persist(store);
    return true;
}

fn session_get::(store, id, k) {
    let s = session_load(store, id);
    if (s == null) { return null; }
    if (@map_has_key(s["data"], k)) { return s["data"][k]; }
    return null;
}

fn session_sweep::(store) {
    let now = @time_ms();
    let alive = {};
    let removed = 0;
    for k in @map_keys_sorted(store["sessions"]) {
        if (store["sessions"][k]["expires"] > now) { alive[k] = store["sessions"][k]; }
        else { removed += 1; }
    }
    store["sessions"] = alive;
    session_persist(store);
    return removed;
}

fn session_count::(store) { return @len(store["sessions"]); }
fn version::() { return "1.0.0"; }
